// Package lintdeep 提供 `hyp lint --deep` 的靜態（編譯期）Schema↔Handler 對齊檢查。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-15
// @ai:purpose 把「handler 綁錯 / 未綁定 Schema 宣告的 Input」這個原本只有 runtime
//
//	BindInput reporter（需實際請求才觸發）能抓到的靜默失敗，提升為「不需啟動 server、
//	不需流量」即可在 CI 攔截的編譯期檢查。本套件刻意獨立於 pkg/manifest，避免讓
//	server 執行檔背上 go/packages 這套重型分析依賴（manifest 被 server import）。
package lintdeep

import (
	"fmt"
	"go/ast"
	"go/constant"
	"go/token"
	"go/types"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const (
	// schemaPkgPath / contextPkgPath 用於以型別路徑精準辨識框架的 Route 與 Context
	schemaPkgPath  = "github.com/maoxiaoyue/hypgo/pkg/schema"
	contextPkgPath = "github.com/maoxiaoyue/hypgo/pkg/context"
	routerPkgPath  = "github.com/maoxiaoyue/hypgo/pkg/router"

	// maxBindDepth 追蹤「handler 把 c 傳給 helper」的最大層數，超過就視為無法確定
	maxBindDepth = 8

	// KindInputMismatch handler 以 BindInput 綁定的型別與 Schema 宣告的 Input 不符
	KindInputMismatch = "deep:input_mismatch"
	// KindNoBindInput 可寫方法的 schema handler 完全未呼叫 BindInput
	KindNoBindInput = "deep:no_bindinput"
)

// Finding 單一深層檢查發現（視為 hard failure）。
type Finding struct {
	Route   string // "POST /api/users"
	Kind    string // KindInputMismatch | KindNoBindInput
	Message string
	Pos     string // file:line（Schema 宣告位置）
}

// Skipped 無法靜態解析的 Schema 路由（誠實揭露，不靜默計入「通過」）。
type Skipped struct {
	Route  string
	Reason string
	Pos    string
}

// Report 深層 lint 結果。
type Report struct {
	Analyzed   int       // 成功解析並檢查的 Schema 路由數
	Findings   []Finding // hard failures
	Skipped    []Skipped // 無法靜態解析者
	LoadErrors []string  // 套件載入/編譯錯誤（有錯時結果不完整，CLI 視為失敗）
}

// funcDef 記錄一個函式宣告與其所屬套件（供解析具名 handler 的本體與型別資訊）。
type funcDef struct {
	decl *ast.FuncDecl
	pkg  *packages.Package
}

// Analyze 對 patterns（預設 "./..."）做靜態 Schema↔Handler 對齊檢查。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-15
// @ai:purpose 載入目標套件的完整型別資訊，找出所有 r.Schema(schema.Route{...}).Handle(h)，
//
//	靜態比對 handler 是否以 c.BindInput 綁定到 Schema 所宣告的 Input 型別，
//	藉此在編譯期攔截綁錯/未綁的靜默失敗
//
// @ai:input dir 為載入工作目錄（go module 內任一路徑）；patterns 為 go 套件樣式（如 "./..."）
// @ai:output *Report（findings / skipped / load errors）；套件載入失敗時回傳 error
// @ai:sideeffect 讀取檔案系統並驅動 go list（packages.Load 內部），無任何寫入
func Analyze(dir string, patterns ...string) (*Report, error) {
	if len(patterns) == 0 {
		patterns = []string{"./..."}
	}
	fset := token.NewFileSet()
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax |
			packages.NeedTypes | packages.NeedTypesInfo | packages.NeedImports | packages.NeedDeps,
		Dir:  dir,
		Fset: fset,
	}
	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		return nil, fmt.Errorf("load packages: %w", err)
	}
	// 目錄存在但沒有 Go 檔時 go list 只警告：先前回報「分析 0 條」並通過
	if len(pkgs) == 0 {
		return nil, fmt.Errorf("no packages matched %v", patterns)
	}

	rep := &Report{}
	packages.Visit(pkgs, nil, func(p *packages.Package) {
		for _, e := range p.Errors {
			rep.LoadErrors = append(rep.LoadErrors, e.Error())
		}
	})

	idx := buildFuncIndex(pkgs)

	for _, p := range pkgs {
		// 框架自己轉呼叫 RegisterSchema 的地方不是路由宣告
		if p.TypesInfo == nil || p.PkgPath == schemaPkgPath || p.PkgPath == routerPkgPath {
			continue
		}
		for _, file := range p.Syntax {
			analyzeFile(file, p, idx, rep)
		}
	}

	sort.Slice(rep.Findings, func(i, j int) bool {
		if rep.Findings[i].Route != rep.Findings[j].Route {
			return rep.Findings[i].Route < rep.Findings[j].Route
		}
		return rep.Findings[i].Kind < rep.Findings[j].Kind
	})
	sort.Slice(rep.Skipped, func(i, j int) bool {
		return rep.Skipped[i].Route < rep.Skipped[j].Route
	})
	return rep, nil
}

// buildFuncIndex 建立 函式物件 → 宣告 的索引，供解析具名 handler 的函式本體。
// 跨已載入套件共享同一 types.Object 實例，因此可解析「Schema 與 handler 不同檔/不同套件」的情形。
// @ai:generated by=claude-opus-4-8 date=2026-06-15
func buildFuncIndex(pkgs []*packages.Package) map[types.Object]funcDef {
	idx := map[types.Object]funcDef{}
	packages.Visit(pkgs, nil, func(p *packages.Package) {
		if p.TypesInfo == nil || len(p.Syntax) == 0 {
			return
		}
		for _, file := range p.Syntax {
			for _, decl := range file.Decls {
				fd, ok := decl.(*ast.FuncDecl)
				if !ok || fd.Body == nil {
					continue
				}
				if obj := p.TypesInfo.Defs[fd.Name]; obj != nil {
					idx[obj] = funcDef{decl: fd, pkg: p}
				}
			}
		}
	})
	return idx
}

// fileAnalyzer 分析單一檔案所需的狀態。
type fileAnalyzer struct {
	p    *packages.Package
	idx  map[types.Object]funcDef
	rep  *Report
	vars map[types.Object]ast.Expr // 區域變數 → 唯一的初始值（被重新賦值者為 nil），供解析 Group 前綴
}

// analyzeFile 以型別辨識檔案內的路由註冊。
// 先前只認 r.Schema(<literal>).Handle(h) 這一種寫法：Route 放變數、表格式註冊、
// SchemaRoute 分開存、RegisterSchema 都完全看不到，連「略過」都不會列出
func analyzeFile(file *ast.File, p *packages.Package, idx map[types.Object]funcDef, rep *Report) {
	a := &fileAnalyzer{p: p, idx: idx, rep: rep, vars: localVars(file, p.TypesInfo)}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := ast.Unparen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		switch sel.Sel.Name {
		case "Handle":
			if isNamedType(p.TypesInfo.TypeOf(sel.X), schemaPkgPath, "SchemaRoute") {
				a.handleCall(call, sel)
			}
		case "RegisterSchema":
			if len(call.Args) > 0 && isSchemaRoute(p.TypesInfo.TypeOf(call.Args[0])) {
				a.inspectRoute(call.Args[0], "", call.Args[1:], call.Ellipsis.IsValid())
			}
		}
		return true
	})
}

// handleCall 處理 <SchemaRoute>.Handle(...)：只有 x.Schema(route).Handle(...) 能對應到 Route 宣告。
func (a *fileAnalyzer) handleCall(call *ast.CallExpr, sel *ast.SelectorExpr) {
	if schemaCall, ok := ast.Unparen(sel.X).(*ast.CallExpr); ok {
		if recv, ok := ast.Unparen(schemaCall.Fun).(*ast.SelectorExpr); ok && recv.Sel.Name == "Schema" && len(schemaCall.Args) == 1 {
			prefix, _ := a.groupPrefix(recv.X) // 解析不到就維持相對路徑，只影響顯示
			a.inspectRoute(schemaCall.Args[0], prefix, call.Args, call.Ellipsis.IsValid())
			return
		}
	}
	a.skip("", "SchemaRoute 先存成變數或由函式回傳，無法對應到 Route 宣告", call)
}

// inspectRoute 從 schema.Route literal 取出 Method/Path/Input，解析終端 handler 並比對綁定。
func (a *fileAnalyzer) inspectRoute(routeExpr ast.Expr, prefix string, handlers []ast.Expr, ellipsis bool) {
	lit, ok := ast.Unparen(routeExpr).(*ast.CompositeLit)
	if !ok {
		a.skip("", "Route 不是字面值（變數或表格式註冊），無法靜態比對", routeExpr)
		return
	}

	var methodExpr, pathExpr, inputExpr ast.Expr
	for _, el := range lit.Elts {
		kv, ok := el.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := kv.Key.(*ast.Ident)
		if !ok {
			continue
		}
		switch key.Name {
		case "Method":
			methodExpr = kv.Value
		case "Path":
			pathExpr = kv.Value
		case "Input":
			inputExpr = kv.Value
		}
	}

	// 先前只認字串字面值：http.MethodPost 變成空字串，no_bindinput 永遠不觸發
	method, methodKnown := "", methodExpr == nil
	if methodExpr != nil {
		if m, ok := a.stringConst(methodExpr); ok {
			method, methodKnown = strings.ToUpper(m), true
		}
	}
	path := ""
	if pathExpr != nil {
		if s, ok := a.stringConst(pathExpr); ok {
			path = s
			if prefix != "" {
				path = joinPath(prefix, s)
			}
		} else {
			path = "(dynamic path)"
		}
	}
	route := strings.TrimSpace(method + " " + path)

	// 沒宣告 Input 的路由由 shallow lint 的 missing_input 負責，深層不重複檢查
	if inputExpr == nil || a.p.TypesInfo.Types[inputExpr].IsNil() {
		return
	}
	if !methodKnown {
		a.skip(strings.TrimSpace("? "+path), "Method 不是常數，無法判斷是否應綁定 body", lit)
		return
	}
	inputType := derefType(a.p.TypesInfo.TypeOf(inputExpr))
	if isUncertain(inputType) {
		a.skip(route, "Input 型別無法靜態確定（介面或型別參數）", lit)
		return
	}

	if len(handlers) == 0 {
		a.skip(route, "Handle 未提供 handler", lit)
		return
	}
	if ellipsis {
		a.skip(route, "handler 以 slice 展開傳入，無法靜態定位終端 handler", lit)
		return
	}
	body, hpkg, ok := resolveHandlerBody(handlers[len(handlers)-1], a.p, a.idx)
	if !ok {
		a.skip(route, "handler 不是具名函式或 inline 函式（工廠函式的回傳值、函式變數或介面方法），無法定位本體", lit)
		return
	}

	scan := &bindScan{idx: a.idx, visited: map[*ast.BlockStmt]bool{}}
	scan.walk(body, hpkg, 0)

	for _, bt := range scan.bound {
		if types.Identical(bt, inputType) {
			a.rep.Analyzed++
			return // 至少一個 BindInput 綁到宣告型別 → 通過
		}
	}
	// 沒看到相符的綁定，但有追不到的呼叫：可能在那裡面綁定，不能判為錯誤
	if scan.unknown && (len(scan.bound) > 0 || isWritable(method)) {
		a.skip(route, "handler 把 c 傳給無法靜態追蹤的函式，或綁定型別不確定（泛型），無法判定", lit)
		return
	}

	a.rep.Analyzed++
	pos := a.pos(lit)
	if len(scan.bound) == 0 {
		if isWritable(method) {
			a.rep.Findings = append(a.rep.Findings, Finding{
				Route:   route,
				Kind:    KindNoBindInput,
				Message: fmt.Sprintf("handler 未呼叫 c.BindInput，宣告的 Input(%s) 不會被解析或驗證（Contract Testing 抓不到此缺口）", typeName(inputType)),
				Pos:     pos,
			})
		}
		return
	}

	got := make([]string, 0, len(scan.bound))
	for _, bt := range scan.bound {
		got = append(got, typeName(bt))
	}
	a.rep.Findings = append(a.rep.Findings, Finding{
		Route:   route,
		Kind:    KindInputMismatch,
		Message: fmt.Sprintf("Schema 宣告 Input=%s，但 handler 以 c.BindInput 綁定 %s（型別不符，請求 body 會靜默綁錯）", typeName(inputType), strings.Join(got, ", ")),
		Pos:     pos,
	})
}

// skip 記錄無法靜態解析的路由；route 為空時以位置標示。
func (a *fileAnalyzer) skip(route, reason string, n ast.Node) {
	pos := a.pos(n)
	if route == "" {
		route = "(non-literal route @ " + pos + ")"
	}
	a.rep.Skipped = append(a.rep.Skipped, Skipped{Route: route, Reason: reason, Pos: pos})
}

func (a *fileAnalyzer) pos(n ast.Node) string {
	return a.p.Fset.Position(n.Pos()).String()
}

// stringConst 取出字串常數值（字面值、具名常數或常數運算式）。
func (a *fileAnalyzer) stringConst(e ast.Expr) (string, bool) {
	v := a.p.TypesInfo.Types[e].Value
	if v == nil || v.Kind() != constant.String {
		return "", false
	}
	return constant.StringVal(v), true
}

// groupPrefix 解析 Schema 呼叫的 receiver 對應的路由前綴：
// router 本身為空字串，NewGroup 串接常數路徑；函式參數、被重新賦值的變數等回 false。
func (a *fileAnalyzer) groupPrefix(e ast.Expr) (string, bool) {
	e = ast.Unparen(e)
	if isNamedType(a.p.TypesInfo.TypeOf(e), routerPkgPath, "Router") {
		return "", true
	}
	switch x := e.(type) {
	case *ast.Ident:
		if init := a.vars[a.p.TypesInfo.Uses[x]]; init != nil {
			return a.groupPrefix(init)
		}
	case *ast.CallExpr:
		sel, ok := ast.Unparen(x.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "NewGroup" || len(x.Args) == 0 {
			return "", false
		}
		rel, ok := a.stringConst(x.Args[0])
		if !ok {
			return "", false
		}
		if base, ok := a.groupPrefix(sel.X); ok {
			return joinPath(base, rel), true
		}
	}
	return "", false
}

// joinPath 串接路由前綴與相對路徑（結果與 router.joinPaths 相同）。
func joinPath(base, rel string) string {
	if rel == "" {
		return base
	}
	return strings.TrimRight(base, "/") + "/" + strings.TrimLeft(rel, "/")
}

// localVars 收集檔案內以 := 宣告的變數初始值；之後又被賦值的記為 nil（值不唯一）。
func localVars(file *ast.File, info *types.Info) map[types.Object]ast.Expr {
	vars := map[types.Object]ast.Expr{}
	ast.Inspect(file, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || len(as.Lhs) != len(as.Rhs) {
			return true
		}
		for i, lhs := range as.Lhs {
			id, ok := lhs.(*ast.Ident)
			if !ok {
				continue
			}
			if obj := info.Defs[id]; obj != nil { // := 重用既有變數時 Defs 沒有這個識別字
				vars[obj] = as.Rhs[i]
			} else if obj := info.Uses[id]; obj != nil {
				vars[obj] = nil
			}
		}
		return true
	})
	return vars
}

// resolveHandlerBody 將函式運算式解析為函式本體（inline func literal、同/跨套件具名函式、method value、泛型實例）。
func resolveHandlerBody(expr ast.Expr, p *packages.Package, idx map[types.Object]funcDef) (*ast.BlockStmt, *packages.Package, bool) {
	var obj types.Object
	switch h := ast.Unparen(expr).(type) {
	case *ast.FuncLit:
		return h.Body, p, true
	case *ast.IndexExpr:
		return resolveHandlerBody(h.X, p, idx)
	case *ast.IndexListExpr:
		return resolveHandlerBody(h.X, p, idx)
	case *ast.Ident:
		obj = p.TypesInfo.Uses[h]
	case *ast.SelectorExpr:
		obj = p.TypesInfo.Uses[h.Sel]
	}
	fn, ok := obj.(*types.Func)
	if !ok {
		return nil, nil, false
	}
	// 泛型 receiver 的方法每個實例都是不同物件，索引裡只有 Origin
	fd, ok := idx[fn.Origin()]
	if !ok {
		return nil, nil, false
	}
	return fd.decl.Body, fd.pkg, true
}

// bindScan 收集 handler（含它把 c 傳去的 helper）裡所有 BindInput 綁定的型別。
type bindScan struct {
	idx     map[types.Object]funcDef
	visited map[*ast.BlockStmt]bool
	bound   []types.Type // 確定的綁定型別
	unknown bool         // 有追不到的呼叫或不確定的型別
}

// walk 掃描函式本體。先前只看 handler 本身：BindInput 放在 helper 會誤報 no_bindinput，
// 綁到 map 或別名時也因為不是具名型別而被當成沒有呼叫。
func (s *bindScan) walk(body *ast.BlockStmt, p *packages.Package, depth int) {
	if s.visited[body] {
		return
	}
	s.visited[body] = true
	if depth > maxBindDepth {
		s.unknown = true
		return
	}

	called := map[*ast.SelectorExpr]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.CallExpr:
			if sel, ok := ast.Unparen(x.Fun).(*ast.SelectorExpr); ok && isContextBindInput(sel, p) {
				called[sel] = true
				if len(x.Args) == 1 {
					s.record(derefType(p.TypesInfo.TypeOf(x.Args[0])))
				}
				return true
			}
			s.followCall(x, p, depth)
		case *ast.SelectorExpr:
			// bind := c.BindInput 這類 method value：不知道之後綁到什麼
			if !called[x] && isContextBindInput(x, p) {
				s.unknown = true
			}
		}
		return true
	})
}

// record 記錄綁定型別；型別不確定（介面、泛型、編譯錯誤）時只標記 unknown。
func (s *bindScan) record(t types.Type) {
	if isUncertain(t) {
		s.unknown = true
		return
	}
	s.bound = append(s.bound, t)
}

// followCall 追蹤把 *Context 或「接收 *Context 的函式」傳出去的呼叫。
// 只看參數宣告為 *Context 的位置：c 當 context.Context 傳給 service 不可能在裡面呼叫 BindInput。
func (s *bindScan) followCall(call *ast.CallExpr, p *packages.Package, depth int) {
	tv := p.TypesInfo.Types[call.Fun]
	if tv.IsType() || tv.Type == nil {
		return // 型別轉換
	}
	sig, ok := tv.Type.Underlying().(*types.Signature)
	if !ok {
		return
	}
	passesContext := false
	for i, arg := range call.Args {
		param := paramType(sig, i, call.Ellipsis.IsValid())
		if param == nil {
			continue
		}
		if isContextPtr(param) {
			passesContext = true
			continue
		}
		// run(c, h.doCreate)：handler 當參數傳遞，它也可能綁定（FuncLit 已由外層 Inspect 涵蓋）
		if fn, ok := param.Underlying().(*types.Signature); ok && takesContext(fn) {
			if _, isLit := ast.Unparen(arg).(*ast.FuncLit); isLit {
				continue
			}
			s.follow(arg, p, depth)
		}
	}
	if passesContext {
		s.follow(call.Fun, p, depth)
	}
}

// follow 解析函式運算式並遞迴掃描；解析不到（介面方法、函式變數）就標記 unknown。
func (s *bindScan) follow(fn ast.Expr, p *packages.Package, depth int) {
	body, fp, ok := resolveHandlerBody(fn, p, s.idx)
	if !ok {
		s.unknown = true
		return
	}
	s.walk(body, fp, depth+1)
}

// paramType 回傳第 i 個引數對應的參數型別（處理 variadic）。
func paramType(sig *types.Signature, i int, ellipsis bool) types.Type {
	params := sig.Params()
	if sig.Variadic() && i >= params.Len()-1 {
		last := params.At(params.Len() - 1).Type()
		if ellipsis {
			return last
		}
		if sl, ok := last.(*types.Slice); ok {
			return sl.Elem()
		}
		return nil
	}
	if i < params.Len() {
		return params.At(i).Type()
	}
	return nil
}

// takesContext 判斷函式型別是否有 *Context 參數。
func takesContext(sig *types.Signature) bool {
	for i := 0; i < sig.Params().Len(); i++ {
		if isContextPtr(sig.Params().At(i).Type()) {
			return true
		}
	}
	return false
}

// isContextPtr 判斷型別是否為 *pkg/context.Context。
func isContextPtr(t types.Type) bool {
	_, isPtr := types.Unalias(t).(*types.Pointer)
	return isPtr && isNamedType(t, contextPkgPath, "Context")
}

// isContextBindInput 確認 selector 指向的是 pkg/context.Context 的 BindInput method（排除同名巧合）。
func isContextBindInput(sel *ast.SelectorExpr, p *packages.Package) bool {
	if sel.Sel.Name != "BindInput" {
		return false
	}
	fn, ok := p.TypesInfo.Uses[sel.Sel].(*types.Func)
	if !ok {
		return false
	}
	sig, ok := fn.Type().(*types.Signature)
	if !ok || sig.Recv() == nil {
		return false
	}
	return isNamedType(sig.Recv().Type(), contextPkgPath, "Context")
}

// isSchemaRoute 判斷型別是否為 pkg/schema.Route。
func isSchemaRoute(t types.Type) bool {
	return isNamedType(t, schemaPkgPath, "Route")
}

// isNamedType 判斷型別去除別名與指標後，是否為指定套件的具名型別。
func isNamedType(t types.Type, pkgPath, name string) bool {
	named, ok := derefType(t).(*types.Named)
	if !ok || named.Obj().Pkg() == nil {
		return false
	}
	return named.Obj().Name() == name && named.Obj().Pkg().Path() == pkgPath
}

// derefType 去除別名與指標層（與 runtime BindInput 的 derefType 一致）。
// 先前只處理 *types.Named：Go 1.23 起別名是獨立的 *types.Alias，會被當成無法解析。
func derefType(t types.Type) types.Type {
	for {
		t = types.Unalias(t)
		ptr, ok := t.(*types.Pointer)
		if !ok {
			return t
		}
		t = ptr.Elem()
	}
}

// isUncertain 判斷型別是否無法靜態確定：沒有型別資訊、編譯錯誤、介面或含型別參數。
func isUncertain(t types.Type) bool {
	return t == nil || t == types.Typ[types.Invalid] || types.IsInterface(t) || mentionsTypeParam(t)
}

// mentionsTypeParam 判斷型別是否含型別參數（T、[]T、Page[T]…）。
func mentionsTypeParam(t types.Type) bool {
	switch x := types.Unalias(t).(type) {
	case *types.TypeParam:
		return true
	case *types.Pointer:
		return mentionsTypeParam(x.Elem())
	case *types.Slice:
		return mentionsTypeParam(x.Elem())
	case *types.Array:
		return mentionsTypeParam(x.Elem())
	case *types.Map:
		return mentionsTypeParam(x.Key()) || mentionsTypeParam(x.Elem())
	case *types.Named:
		for i := 0; i < x.TypeArgs().Len(); i++ {
			if mentionsTypeParam(x.TypeArgs().At(i)) {
				return true
			}
		}
	}
	return false
}

// isWritable 判斷是否為通常帶請求 body 的方法（與 pkg/manifest 的 shallow lint 一致）。
func isWritable(method string) bool {
	switch method {
	case "POST", "PUT", "PATCH":
		return true
	default:
		return false
	}
}

// typeName 產生 套件.型別 形式的可讀名稱。
func typeName(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string { return p.Name() })
}

// Format 將 Report 格式化為人類可讀的多行報告（供 CLI 輸出）。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-15
// @ai:purpose 以正向指標（已分析數）＋ 明列略過項，呈現深層檢查結果，避免「綠燈＝全覆蓋」的假象
// @ai:input *Report（可為 nil）
// @ai:output 多行報告字串
// @ai:sideeffect none
func Format(rep *Report) string {
	if rep == nil {
		return ""
	}
	var b strings.Builder
	b.WriteString("深層 Schema↔Handler 檢查（--deep）\n")
	b.WriteString("─────────────────────────────────────────────\n")

	if len(rep.LoadErrors) > 0 {
		b.WriteString(fmt.Sprintf("⚠ 套件載入有 %d 個錯誤（分析不完整，視為失敗）：\n", len(rep.LoadErrors)))
		for _, e := range rep.LoadErrors {
			b.WriteString("    " + e + "\n")
		}
	}

	for _, f := range rep.Findings {
		b.WriteString(fmt.Sprintf("  ⚠ [%s] %s — %s\n      ↳ %s\n", f.Kind, f.Route, f.Message, f.Pos))
	}
	// 先前載入失敗或分析 0 條時也印「✓ 皆對齊」
	if len(rep.Findings) == 0 && len(rep.LoadErrors) == 0 {
		switch {
		case rep.Analyzed > 0:
			b.WriteString(fmt.Sprintf("✓ 已分析 %d 條 Schema 路由，handler 綁定皆對齊宣告\n", rep.Analyzed))
		case len(rep.Skipped) == 0:
			b.WriteString("沒有可檢查的路由（未找到宣告 Input 的 Schema 路由）\n")
		}
	}

	if len(rep.Skipped) > 0 {
		b.WriteString(fmt.Sprintf("略過（無法靜態解析，未計入通過）：%d 條\n", len(rep.Skipped)))
		for _, s := range rep.Skipped {
			b.WriteString(fmt.Sprintf("  - %s：%s（%s）\n", s.Route, s.Reason, s.Pos))
		}
	}

	b.WriteString(fmt.Sprintf("深層檢查：分析 %d 條、問題 %d 個、略過 %d 條、載入錯誤 %d 個", rep.Analyzed, len(rep.Findings), len(rep.Skipped), len(rep.LoadErrors)))
	return b.String()
}
